<?php
require __DIR__.'/../config/database.php';require __DIR__.'/../includes/functions.php';require_role(['student']);$q=$pdo->prepare('SELECT a.*,s.title,(SELECT COUNT(*) FROM application_documents d WHERE d.application_id=a.application_id) doc_count,(SELECT COUNT(*) FROM application_documents d WHERE d.application_id=a.application_id AND d.review_status="Rejected") rejected_docs FROM applications a JOIN scholarships s ON s.scholarship_id=a.scholarship_id WHERE a.student_id=? ORDER BY a.submitted_at DESC');$q->execute([(int)$_SESSION['user_id']]);$rows=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 10');$q->execute([(int)$_SESSION['user_id']]);$notes=$q->fetchAll();$pageTitle='My Applications';require __DIR__.'/../includes/header.php';?>
<h1>My applications</h1><div class="application-status-list"><?php foreach($rows as $r):?><article class="panel application-status-card"><div><h2><?=e($r['title'])?></h2><p class="muted">Submitted <?=e($r['submitted_at'])?></p></div><span class="status-pill"><?=e($r['status'])?></span><p>Supporting documents uploaded: <?=(int)$r['doc_count']?><?php if($r['rejected_docs']):?> · <span class="warning"><?=(int)$r['rejected_docs']?> document(s) need attention</span><?php endif;?></p></article><?php endforeach;?></div><?php if(!$rows):?><p>You have not submitted any applications.</p><?php endif;?>
<h2>Notifications</h2><?php foreach($notes as $n):?><p class="notice"><?=e($n['message'])?> <small><?=e($n['created_at'])?></small></p><?php endforeach;?><?php require __DIR__.'/../includes/footer.php';?>
